// Generate Report Metadata
// Produces exactly ONE item holding the identity of today's report.
// The workflow timezone is Asia/Karachi, so $now is already local time.

// RFC-4122 v4 UUID using only standard JavaScript (no npm imports, no crypto
// module) so it is safe on n8n Cloud.
function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

return [
  {
    json: {
      report_uuid: uuidv4(),
      report_date: $now.toFormat('yyyy-MM-dd'),
      generated_at: $now.toISO(),
    },
  },
];

// Calculate Report Statistics
// Collapses the metadata item and ALL PostgreSQL result sets into exactly ONE
// item. This is the node that guarantees one AI call, one Supabase row and one
// email per execution.

const meta = $('Generate Report Metadata').first().json;
const metrics = $('PostgreSQL - Get Daily Metrics').first().json;

function toInt(value) {
  const n = Number(value);
  return Number.isFinite(n) ? Math.trunc(n) : 0;
}

function toNum(value) {
  const n = Number(value);
  return Number.isFinite(n) ? Number(n.toFixed(2)) : 0;
}

function toText(value, fallback) {
  if (value === null || value === undefined || value === '') return fallback;
  return String(value);
}

const totalLeads = toInt(metrics.total_leads);
const newLeads = toInt(metrics.new_leads);
const qualifiedLeads = toInt(metrics.qualified_leads);
const convertedLeads = toInt(metrics.converted_leads);
const averageLeadScore = toNum(metrics.average_lead_score);

// --- Top source -----------------------------------------------------------
// Returns at most one row, and NO rows when the leads table is empty.
// "Always Output Data" is enabled on that node, so an empty run yields {}.
let topSource = 'N/A';
let topSourceLeadCount = 0;
const topSourceRows = $('PostgreSQL - Get Top Source').all();
if (topSourceRows.length > 0 && topSourceRows[0].json && topSourceRows[0].json.source) {
  topSource = String(topSourceRows[0].json.source);
  topSourceLeadCount = toInt(topSourceRows[0].json.lead_count);
}

// --- Top 5 leads ----------------------------------------------------------
// 0..5 rows flattened into ONE array. The `id` guard drops the placeholder
// item that "Always Output Data" emits when the query matched nothing.
const top5Leads = $('PostgreSQL - Get Top 5 Leads')
  .all()
  .map(function (item) {
    return item.json;
  })
  .filter(function (row) {
    return row && row.id !== undefined && row.id !== null;
  })
  .map(function (row) {
    return {
      id: toInt(row.id),
      lead_uuid: row.lead_uuid === null || row.lead_uuid === undefined ? null : String(row.lead_uuid),
      name: toText(row.name, 'N/A'),
      company: toText(row.company, 'N/A'),
      source: toText(row.source, 'N/A'),
      lead_score: toInt(row.lead_score),
      lead_status: toText(row.lead_status, 'N/A'),
      lead_category: toText(row.lead_category, 'N/A'),
      is_converted: row.is_converted === true,
    };
  });

// --- Source performance ---------------------------------------------------
// 0..N rows flattened into ONE array so the AI can comment on per-source
// performance without inventing it.
const sourcePerformance = $('PostgreSQL - Get Source Performance')
  .all()
  .map(function (item) {
    return item.json;
  })
  .filter(function (row) {
    return row && row.source !== undefined && row.source !== null;
  })
  .map(function (row) {
    return {
      source: String(row.source),
      total_leads: toInt(row.total_leads),
      qualified_leads: toInt(row.qualified_leads),
      converted_leads: toInt(row.converted_leads),
      qualification_rate: toNum(row.qualification_rate),
      conversion_rate: toNum(row.conversion_rate),
      average_score: toNum(row.average_score),
    };
  });

// --- Conversion rate ------------------------------------------------------
const conversionRate =
  totalLeads > 0 ? Number(((convertedLeads / totalLeads) * 100).toFixed(2)) : 0;

return [
  {
    json: {
      report_uuid: meta.report_uuid,
      report_date: meta.report_date,
      generated_at: meta.generated_at,

      total_leads: totalLeads,
      new_leads: newLeads,
      qualified_leads: qualifiedLeads,
      converted_leads: convertedLeads,
      average_lead_score: averageLeadScore,

      top_source: topSource,
      top_source_lead_count: topSourceLeadCount,

      conversion_rate: conversionRate,

      top_5_leads: top5Leads,
      source_performance: sourcePerformance,
    },
  },
];

// Prepare AI Report Data
// Builds ONE clean, serialized prompt payload containing only values that were
// calculated from the database. The AI is never asked to compute a metric.

const r = $('Calculate Report Statistics').first().json;

function dp2(value) {
  return Number(value).toFixed(2);
}

const topLeadsText =
  r.top_5_leads.length === 0
    ? 'No scored leads available.'
    : r.top_5_leads
        .map(function (lead, index) {
          return (
            String(index + 1) +
            '. ' +
            lead.name +
            ' | Company: ' +
            lead.company +
            ' | Source: ' +
            lead.source +
            ' | Score: ' +
            lead.lead_score +
            ' | Status: ' +
            lead.lead_status +
            ' | Converted: ' +
            (lead.is_converted ? 'Yes' : 'No')
          );
        })
        .join('\n');

const sourceText =
  r.source_performance.length === 0
    ? 'No source-level performance data available.'
    : r.source_performance
        .map(function (s) {
          return (
            '- ' +
            s.source +
            ': total ' +
            s.total_leads +
            ', qualified ' +
            s.qualified_leads +
            ' (' +
            dp2(s.qualification_rate) +
            '%), converted ' +
            s.converted_leads +
            ' (' +
            dp2(s.conversion_rate) +
            '%), average score ' +
            dp2(s.average_score)
          );
        })
        .join('\n');

const aiInput = [
  'Report Date: ' + r.report_date,
  'Total Leads: ' + r.total_leads,
  'New Leads: ' + r.new_leads,
  'Qualified Leads: ' + r.qualified_leads,
  'Converted Leads: ' + r.converted_leads,
  'Average Lead Score: ' + dp2(r.average_lead_score),
  'Top Source: ' + r.top_source + ' (' + r.top_source_lead_count + ' leads)',
  'Conversion Rate: ' + dp2(r.conversion_rate) + '%',
  '',
  'Top 5 Leads:',
  topLeadsText,
  '',
  'Source Performance:',
  sourceText,
  '',
  'Write a concise manager-level observation using only this information.',
].join('\n');

return [{ json: { ai_input: aiInput } }];

// Compose Final Report
// Builds the deterministic manager-facing report text. The AI controls only the
// summary paragraph, never the report structure or the numbers.
//
// This node also resolves the EFFECTIVE report_uuid: report_date is UNIQUE in
// Supabase, so a re-run on the same day reuses the stored UUID. Doing it here
// (before storage and before Gmail) keeps the email, the report text and the
// Supabase row on one identity.

const r = $('Calculate Report Statistics').first().json;

// --- AI summary, never fabricated ----------------------------------------
const AI_FALLBACK =
  'AI summary unavailable for this execution. Verified database metrics are shown above.';

let aiSummary = AI_FALLBACK;
try {
  const aiRows = $('AI - Generate Business Summary').all();
  if (aiRows.length > 0 && aiRows[0].json) {
    // Basic LLM Chain returns the model response on the `text` field.
    const raw = aiRows[0].json.text;
    if (typeof raw === 'string' && raw.trim() !== '') {
      aiSummary = raw.trim();
    }
  }
} catch (error) {
  aiSummary = AI_FALLBACK;
}

// --- Existing Supabase report for this report_date ------------------------
let reportExists = false;
let existingReportId = null;
let effectiveUuid = r.report_uuid;

const foundRows = $('Supabase - Find Existing Report').all();
if (
  foundRows.length > 0 &&
  foundRows[0].json &&
  foundRows[0].json.id !== undefined &&
  foundRows[0].json.id !== null
) {
  reportExists = true;
  existingReportId = foundRows[0].json.id;
  if (foundRows[0].json.report_uuid) {
    effectiveUuid = String(foundRows[0].json.report_uuid);
  }
}

function dp2(value) {
  return Number(value).toFixed(2);
}

const topLeadsBlock =
  r.top_5_leads.length === 0
    ? 'No scored leads available.'
    : r.top_5_leads
        .map(function (lead, index) {
          return (
            String(index + 1) +
            '. ' +
            lead.name +
            ' | ' +
            lead.company +
            ' | ' +
            lead.source +
            ' | Score: ' +
            lead.lead_score +
            ' | Status: ' +
            lead.lead_status
          );
        })
        .join('\n');

const finalReport = [
  'DAILY LEAD REPORT',
  '',
  'Report Date: ' + r.report_date,
  '',
  'KEY METRICS',
  '',
  'Total Leads: ' + r.total_leads,
  'New Leads: ' + r.new_leads,
  'Qualified Leads: ' + r.qualified_leads,
  'Converted Leads: ' + r.converted_leads,
  'Average Lead Score: ' + dp2(r.average_lead_score),
  'Top Source: ' + r.top_source,
  'Conversion Rate: ' + dp2(r.conversion_rate) + '%',
  '',
  'TOP 5 LEADS',
  '',
  topLeadsBlock,
  '',
  'AI BUSINESS SUMMARY',
  '',
  aiSummary,
  '',
  'Report UUID: ' + effectiveUuid,
].join('\n');

return [
  {
    json: {
      // ---- columns of public.daily_lead_reports ----------------------------
      // These are auto-mapped straight into Supabase, so top_5_leads stays a
      // real JS array and reaches the JSONB column as a JSON array.
      report_uuid: effectiveUuid,
      report_date: r.report_date,
      total_leads: r.total_leads,
      new_leads: r.new_leads,
      qualified_leads: r.qualified_leads,
      converted_leads: r.converted_leads,
      average_lead_score: r.average_lead_score,
      top_source: r.top_source,
      conversion_rate: r.conversion_rate,
      top_5_leads: r.top_5_leads,
      ai_summary: aiSummary,
      delivery_status: 'pending',
      generated_at: r.generated_at,

      // ---- workflow-only fields -------------------------------------------
      // Listed in "Inputs to Ignore" on both Supabase write nodes so they are
      // never sent as columns.
      final_report: finalReport,
      report_exists: reportExists,
      existing_report_id: existingReportId,
    },
  },
];
